DROP TRIGGER loan_late_payment_evidence ON "${schema}".loan_posting;
DROP FUNCTION "${schema}".loan_validate_late_payment();
DROP FUNCTION "${schema}".loan_is_reviewed_late_adjustment("${schema}".loan_posting);
